53	@@ -0,0 +1,75 @@
54	+// The dashboard is unauthenticated: nothing but the browser's own preflight
55	+// rules stand between a page on the LAN and the laugh log. `dashboard.py`'s
56	+// do_POST therefore rejects anything that isn't `application/json` before it
57	+// touches the database — a content type a cross-origin `fetch` cannot send
58	+// without a CORS preflight the dashboard never answers. That guard is the whole
59	+// CSRF story, so a *new* mutating handler that forgets it silently reopens the
60	+// hole. Parses the handler body by indentation rather than grepping the file,
61	+// so the guard has to live in the handler that needs it — `application/json`
62	+// elsewhere in the module (response content types, the inline page's fetch)
63	+// doesn't count.
64	+// Dependency-free (a local pack loads without the canon mount): plain findings.
65	+
66	+// BaseHTTPRequestHandler dispatches `do_<VERB>`; these are the ones that mutate.
67	+const MUTATING_HANDLER = /^(\s*)(?:async\s+)?def\s+(do_(?:POST|PUT|PATCH|DELETE))\s*\(/;
68	+
69	+// The request's own content type being read — `self.headers.get("Content-Type")`
70	+// or `self.headers["Content-Type"]`, however it is spelled/cased.
71	+const READS_CONTENT_TYPE = /\.headers\s*(?:\.get\s*\(\s*|\[\s*)["']content-type["']/i;
72	+
73	+// A conditional that turns on it. Requiring the `if` (not just the literal)
74	+// keeps a handler that merely *replies* in JSON from passing.
75	+const GUARDS_ON_JSON = /^\s*(?:el)?if\b.*application\/json/;
76	+
77	+// The handler body: every line indented deeper than its `def`, up to the first
78	+// non-blank line that dedents back out.
79	+function bodyOf(lines, defIndex, indent) {
80	+  const body = [];
81	+  for (let i = defIndex + 1; i < lines.length; i += 1) {
82	+    const line = lines[i];
83	+    if (line.trim() === '') { body.push(line); continue; }
84	+    const lead = line.length - line.trimStart().length;
85	+    if (lead <= indent) break;
86	+    body.push(line);
87	+  }
88	+  return body;
89	+}
90	+
91	+const rule = {
92	+  id: 'on-device-privacy/json-content-type-guard',
93	+  severity: 'blocking',
94	+  description: 'Every mutating dashboard handler must reject non-application/json requests',
95	+  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
96	+  why: 'the dashboard has no authentication — the application/json content-type requirement is the only thing forcing a cross-origin browser to preflight, and so the only thing stopping any page the user visits from writing to their laugh log',
97	+
98	+  run(ctx) {
99	+    const out = [];
100	+    for (const file of ctx.files.filter((f) => f.startsWith('laughcounter/') && f.endsWith('.py'))) {
101	+      const text = ctx.read(file);
102	+      if (text === null) continue;
103	+      const lines = text.split('\n');
104	+      for (let i = 0; i < lines.length; i += 1) {
105	+        const m = MUTATING_HANDLER.exec(lines[i]);
106	+        if (m === null) continue;
107	+        const [, indentText, name] = m;
108	+        const body = bodyOf(lines, i, indentText.length);
109	+        const readsType = body.some((l) => READS_CONTENT_TYPE.test(l));
110	+        const guards = body.some((l) => GUARDS_ON_JSON.test(l));
111	+        if (readsType && guards) continue;
112	+        out.push({
113	+          rule: rule.id,
114	+          severity: rule.severity,
115	+          file,
116	+          line: i + 1,
117	+          what: `${name}() mutates without requiring an application/json content type`,
118	+          why: rule.why,
119	+          fix: 'read the request\'s Content-Type first and reply 415 unless it is application/json, before doing any work (see do_POST in laughcounter/dashboard.py)',
120	+          doc: rule.doc,
121	+        });
122	+      }
123	+    }
124	+    return out;
125	+  },
126	+};
127	+
128	+export default rule;
