176	+      + '            drop_everything()\n',
177	+  }));
178	+  assert.equal(findings.length, 2);
179	+  assert.deepEqual(findings.map((f) => f.line), [2, 6]);
180	+  assert.match(findings[0].what, /do_POST\(\) mutates/);
181	+  assert.match(findings[1].what, /do_DELETE\(\) mutates/);
182	+});
183	+
184	+test('json-content-type-guard is not fooled by a JSON *response* type', () => {
185	+  // `application/json` appears three times here, never as a request guard.
186	+  const findings = jsonContentTypeGuard.run(ctxOf({
187	+    'laughcounter/dashboard.py':
188	+      '        def do_POST(self):\n'
189	+      + '            ctype = self.headers.get("Content-Type", "")\n'
190	+      + '            self._send(200, "application/json", b"{}")\n',
191	+  }));
192	+  assert.equal(findings.length, 1);
193	+});
194	+
195	+test('json-content-type-guard stays quiet on the real dashboard', () => {
196	+  const findings = jsonContentTypeGuard.run(realCtx(
197	+    'laughcounter/dashboard.py',
198	+    'laughcounter/cli.py',
199	+    'laughcounter/storage.py',
200	+  ));
201	+  assert.deepEqual(findings, []);
202	+});
203	+
204	+test('single-home-dir fires on state scattered outside ~/.laughcounter', () => {
205	+  const findings = singleHomeDir.run(ctxOf({
206	+    'laughcounter/cache.py': 'CACHE = Path.home() / ".cache" / "laughcounter"\n',
207	+    'laughcounter/speaker.py': '    savedir=os.path.expanduser("~/Library/Caches/ecapa"),\n',
208	+  }));
209	+  assert.equal(findings.length, 2);
210	+  assert.match(findings[0].what, /Path\.home\(\) is used without landing under \.laughcounter/);
211	+  assert.match(findings[1].what, /~\/Library\/Caches\/ecapa/);
212	+});
213	+
214	+test('single-home-dir exempts the OS-mandated LaunchAgents path', () => {
215	+  const findings = singleHomeDir.run(ctxOf({
216	+    'laughcounter/cli.py': '    dest = f"~/Library/LaunchAgents/{label}.plist"\n',
217	+  }));
218	+  assert.deepEqual(findings, []);
219	+});
220	+
221	+test('single-home-dir stays quiet on the real home-anchored paths', () => {
222	+  const findings = singleHomeDir.run(realCtx(
223	+    'laughcounter/config.py',    // Path.home() / ".laughcounter"
224	+    'laughcounter/speaker.py',   // expanduser("~/.laughcounter/models/ecapa")
225	+    'laughcounter/clips.py',
226	+    'laughcounter/storage.py',
227	+    'laughcounter/cli.py',
228	+  ));
229	+  assert.deepEqual(findings, []);
