231	diff --git a/.claudinite/local/packs/on-device-privacy/single-home-dir.mjs b/.claudinite/local/packs/on-device-privacy/single-home-dir.mjs
232	new file mode 100644
233	index 0000000..8fc28f3
234	--- /dev/null
235	+++ b/.claudinite/local/packs/on-device-privacy/single-home-dir.mjs
236	@@ -0,0 +1,84 @@
237	+// "Delete the folder and it's gone" is a documented privacy property, not a
238	+// tidiness one: everything the Python core keeps about the room — the SQLite
239	+// rows, the JSONL log, the saved clips, downloaded model weights — lives under
240	+// the single directory `home_dir()` returns (`~/.laughcounter`, or
241	+// `LAUGHCOUNTER_HOME`). State that lands somewhere else survives the delete the
242	+// user was told was enough. This check holds the mechanical half: a path
243	+// *anchored at the user's home* inside `laughcounter/` must land under
244	+// `.laughcounter`. Two spellings reach the home directory in this codebase —
245	+// `Path.home()` and a `~/…` string literal (`expanduser`, `Path(...).expanduser()`)
246	+// — and both are checked, minus a short list of locations the OS itself dictates
247	+// (see OS_MANDATED). An absolute path outside `$HOME` is still a judgment call
248	+// left to RULES.md.
249	+// Dependency-free (a local pack loads without the canon mount): plain findings.
250	+
251	+const HOME_CALL = /\bPath\.home\s*\(\s*\)/;
252	+const TILDE_LITERAL = /(["'])(~\/[^"']*)\1/g;
253	+
254	+// The one directory everything hangs off, however it is spelled at the call site.
255	+const UNDER_HOME_DIR = /\.laughcounter\b/;
256	+
257	+// Mandated-location exemption: a launchd agent is registered by *being* a file
258	+// in `~/Library/LaunchAgents/` — the OS picks the path, the project doesn't. It
259	+// carries no captured data (`cmd_service` points its log back at `home_path`),
260	+// so deleting `~/.laughcounter` still takes everything about the room with it.
261	+// Keep this list to locations an OS genuinely dictates; a cache or a model dir
262	+// is a choice, and a choice belongs under the home directory.
263	+const OS_MANDATED = [/^~\/Library\/LaunchAgents\//];
264	+
265	+const rule = {
266	+  id: 'on-device-privacy/single-home-dir',
267	+  severity: 'blocking',
268	+  description: 'Home-anchored paths in laughcounter/ must live under the LaughCounter home directory',
269	+  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
270	+  why: '"delete ~/.laughcounter and it is gone" is a privacy promise the README makes — state written anywhere else in the user\'s home outlives the deletion they were told was enough',
271	+
272	+  run(ctx) {
273	+    const out = [];
274	+    for (const file of ctx.files.filter((f) => f.startsWith('laughcounter/') && f.endsWith('.py'))) {
275	+      const text = ctx.read(file);
276	+      if (text === null) continue;
277	+      const lines = text.split('\n');
278	+      for (let i = 0; i < lines.length; i += 1) {
279	+        const line = lines[i];
280	+
281	+        // `Path.home()` is only legal where it is joined to the home directory
282	+        // on the spot (config.py's `Path.home() / ".laughcounter"`).
283	+        if (HOME_CALL.test(line) && !UNDER_HOME_DIR.test(line)) {
284	+          out.push({
285	+            rule: rule.id,
286	+            severity: rule.severity,
287	+            file,
288	+            line: i + 1,
289	+            what: 'Path.home() is used without landing under .laughcounter',
290	+            why: rule.why,
291	+            fix: 'hang the path off home_dir() from laughcounter/config.py instead of reaching into the user home directly',
292	+            doc: rule.doc,
293	+          });
294	+        }
295	+
296	+        TILDE_LITERAL.lastIndex = 0;
297	+        let m = TILDE_LITERAL.exec(line);
298	+        while (m !== null) {
299	+          const literal = m[2];
300	+          if (!literal.startsWith('~/.laughcounter') && !OS_MANDATED.some((p) => p.test(literal))) {
301	+            out.push({
302	+              rule: rule.id,
303	+              severity: rule.severity,
304	+              file,
305	+              line: i + 1,
306	+              what: `the home-anchored path "${literal}" is outside ~/.laughcounter`,
307	+              why: rule.why,
308	+              fix: 'move it under the LaughCounter home directory — use home_dir() from laughcounter/config.py so LAUGHCOUNTER_HOME keeps working',
309	+              doc: rule.doc,
310	+            });
311	+          }
312	+          m = TILDE_LITERAL.exec(line);
313	+        }
314	+      }
315	+    }
316	+    return out;
317	+  },
318	+};
319	+
320	+export default rule;
