+  const body = [];
+  for (let i = defIndex + 1; i < lines.length; i += 1) {
+    const line = lines[i];
+    if (line.trim() === '') { body.push(line); continue; }
+    const lead = line.length - line.trimStart().length;
+    if (lead <= indent) break;
+    body.push(line);
+  }
+  return body;
+}
