63	+// The dashboard is unauthenticated: nothing but the loopback bind stands between
64	+// the LAN and the laugh log. The one thing that stands between a *hostile page in
65	+// the user's browser* and the mutating endpoints is the `application/json`
66	+// content-type requirement — a browser cannot send that cross-origin without a
67	+// preflight, so requiring it is the dashboard's whole CSRF story. Every mutating
68	+// http.server handler therefore has to reject a non-JSON content type, and reject
69	+// it *before* it reads the request body or acts on it.
70	+//
71	+// Detection parses structure rather than grepping text: the handler's body is cut
72	+// out by indentation, so the guard has to be inside the handler that needs it —
73	+// `application/json` appears all over dashboard.py as a *response* content type,
74	+// and a whole-file grep would happily accept those.
75	+//
76	+// Dependency-free by design (a local pack must load without the canon mount), so
77	+// the finding object is built by hand rather than via the engine helper.
78	+
79	+// BaseHTTPRequestHandler's mutating verbs. do_GET/do_HEAD are read-only and are
80	+// deliberately out of scope.
81	+const HANDLER = /^(\s*)def\s+(do_(?:POST|PUT|PATCH|DELETE))\s*\(/;
82	+
83	+const READS_CONTENT_TYPE = /["']Content-Type["']/i;
84	+const REQUIRES_JSON = /application\/json/;
85	+const GUARD_WINDOW = 4;
86	+// Consuming or dispatching the request — everything the guard must precede.
87	+const CONSUMES_BODY = /\bself\.rfile\.read\b|\b_read_json\s*\(|\bjson\.loads\s*\(/;
88	+
89	+const indentOf = (line) => line.length - line.trimStart().length;
90	+
91	+// The handler's body: the run of lines indented deeper than its `def`.
92	+const bodyOf = (lines, defIndex, defIndent) => {
93	+  const body = [];
94	+  for (let i = defIndex + 1; i < lines.length; i += 1) {
95	+    const line = lines[i];
96	+    if (line.trim() === '') {
97	+      body.push({ line, index: i });
98	+      continue;
99	+    }
100	+    if (indentOf(line) <= defIndent) break;
101	+    body.push({ line, index: i });
102	+  }
103	+  return body;
104	+};
105	+
106	+const rule = {
107	+  id: 'on-device-privacy/json-content-type-guard',
108	+  severity: 'blocking',
109	+  description: 'Every mutating dashboard handler must require an application/json content type, before reading the body',
110	+  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
111	+  why: 'the dashboard has no authentication — the JSON content-type requirement is the only thing forcing a cross-origin browser to preflight, so dropping it hands any page the user visits a write handle on their laugh log',
112	+
113	+  run(ctx) {
114	+    const out = [];
115	+    const add = (file, line, what, fix) =>
116	+      out.push({ rule: rule.id, severity: rule.severity, file, line, what, why: rule.why, fix, doc: rule.doc });
117	+
118	+    for (const file of ctx.files.filter((f) => f.startsWith('laughcounter/') && f.endsWith('.py'))) {
119	+      const text = ctx.read(file);
120	+      if (text === null) continue;
121	+      const lines = text.split('\n');
122	+
123	+      for (let i = 0; i < lines.length; i += 1) {
124	+        const m = HANDLER.exec(lines[i]);
125	+        if (m === null) continue;
126	+        const [, indent, name] = m;
127	+        const body = bodyOf(lines, i, indent.length);
128	+
129	+        const guardAt = body.findIndex(
130	+          (b, j) =>
131	+            READS_CONTENT_TYPE.test(b.line)
132	+            && body.slice(j, j + GUARD_WINDOW).some((w) => REQUIRES_JSON.test(w.line)),
133	+        );
134	+        if (guardAt === -1) {
135	+          add(
136	+            file,
137	+            i + 1,
138	+            `${name} never requires an application/json content type`,
139	+            'read Content-Type and return 415 unless it is application/json, before touching the request body',
140	+          );
141	+          continue;
142	+        }
143	+
144	+        const consumesAt = body.findIndex((b) => CONSUMES_BODY.test(b.line));
145	+        if (consumesAt !== -1 && consumesAt < guardAt) {
146	+          add(
147	+            file,
148	+            body[consumesAt].index + 1,
149	+            `${name} reads the request body before it checks the content type`,
150	+            'move the application/json guard above the body read so a non-JSON request is rejected without being acted on',
151	+          );
152	+        }
153	+      }
154	+    }
155	+    return out;
156	+  },
157	+};
158	+
159	+export default rule;
