272	+// belongs in *one* deletable directory per implementation — `~/.laughcounter` for
273	+// the Python core (overridable via LAUGHCOUNTER_HOME) and
274	+// `~/Library/Application Support/LaughCounter/` for the native app. State that
275	+// lands anywhere else (a cache, a model dir, a log) breaks the documented
276	+// property that removing that one folder removes everything the mic ever heard
277	+// about you.
278	+//
279	+// So this scans the two runtime trees for *home-anchored* path literals and for
280	+// the Foundation standard-directory API, and requires each to land inside the one
281	+// directory. It matches the literal forms the code actually uses — a `~/…` string,
282	+// `Path.home() / "…"`, `urls(for: .someDirectory)`, `NSHomeDirectory()` — rather
283	+// than every conceivable path expression, so it stays free of false alarms.
284	+//
285	+// One documented exemption: `~/Library/LaunchAgents/…`. launchd mandates that
286	+// location for a login agent and the app never writes it — `laughcounter service`
287	+// only prints the plist and tells the user where to redirect it.
288	+//
289	+// Dependency-free by design (a local pack must load without the canon mount), so
290	+// the finding object is built by hand rather than via the engine helper.
291	+
292	+const PY_HOME = '.laughcounter';
293	+const MAC_DIR = 'LaughCounter';
294	+
295	+// launchd's mandated location — not app state, and not written by the app.
296	+const HOME_EXEMPT = [/^Library\/LaunchAgents(\/|$)/];
297	+
298	+// `Path.home() / "seg"` — the join's first literal segment.
299	+const PATH_HOME_JOIN = /\bPath\.home\(\)\s*\/\s*["']([^"']*)["']/g;
300	+// Any quoted `~/…` literal (expanduser arguments, f-strings, plain paths).
301	+const TILDE_LITERAL = /["']~\/([^"']*)["']/g;
302	+
303	+// `FileManager.default.urls(for: .applicationSupportDirectory, …)` — the standard
304	+// directory being asked for. Scoped to the `urls(for:` call so that unrelated
305	+// selectors ending in "Directory" (`.createDirectory`, `withIntermediateDirectories`)
306	+// can't trip it.
307	+const URLS_FOR_DIRECTORY = /\burls\s*\(\s*for:\s*\.(\w+)Directory\b/g;
308	+const NS_HOME_DIRECTORY = /\bNSHomeDirectory\s*\(\s*\)/;
309	+// The Application Support base is only legal once narrowed to LaughCounter/.
310	+const NARROWED = new RegExp(`appendingPathComponent\\(\\s*["']${MAC_DIR}["']`);
311	+const NARROW_WINDOW = 8;
312	+
313	+const firstSegment = (path) => path.split('/')[0];
314	+const exempt = (path) => HOME_EXEMPT.some((p) => p.test(path));
315	+
316	+const rule = {
317	+  id: 'on-device-privacy/single-home-directory',
318	+  severity: 'blocking',
319	+  description:
320	+    'Persisted state stays in the one deletable directory (~/.laughcounter, ~/Library/Application Support/LaughCounter)',
321	+  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
322	+  why: '"delete the folder and it\'s gone" is a documented privacy property — state scattered outside that one directory survives the delete the user thinks removed everything',
