368	+                i + 1,
369	+                `state is placed in the .${which}Directory, not Application Support/${MAC_DIR}`,
370	+                `use .applicationSupportDirectory and narrow it with appendingPathComponent("${MAC_DIR}")`,
371	+              );
372	+            } else if (!NARROWED.test(lines.slice(i, i + NARROW_WINDOW).join('\n'))) {
373	+              add(
