// The dashboard is unauthenticated: nothing but the browser's own preflight rules
// stand between a page the user happens to be visiting and the laugh log.
// `dashboard.py`'s do_POST therefore rejects anything that isn't
// `application/json` before it touches the request body — a content type a
// cross-origin `fetch` cannot send without a CORS preflight the dashboard never
// answers. That guard is the whole CSRF story, so a *new* mutating handler that
// forgets it, or one that reads the body before checking, silently reopens the
// hole.
//
// Detection parses structure rather than grepping text: the handler's body is cut
// out by indentation, so the guard has to live inside the handler that needs it.
// `application/json` appears eight times in dashboard.py as a *response* content
// type plus once in the inline page's `fetch()`, and a whole-file grep would
// happily accept every one of them.
//
// Dependency-free by design (a local pack must load without the canon mount), so
// the finding object is built by hand rather than via the engine helper.

// BaseHTTPRequestHandler dispatches `do_<VERB>`; these are the ones that mutate.
// do_GET/do_HEAD are read-only and deliberately out of scope.
const MUTATING_HANDLER = /^(\s*)(?:async\s+)?def\s+(do_(?:POST|PUT|PATCH|DELETE))\s*\(/;

// The *request's* content type being read — `self.headers.get("Content-Type")` or
// `self.headers["Content-Type"]`, however spelled or cased. Anchoring on
// `.headers` is what keeps `send_header("Content-Type", …)` on the response side
// from counting as a guard.
const READS_CONTENT_TYPE = /\.headers\s*(?:\.get\s*\(\s*|\[\s*)["']content-type["']/i;

// A conditional that turns on it. Requiring the `if` (not just the literal) keeps
// a handler that merely *replies* in JSON from passing.
const GUARDS_ON_JSON = /^\s*(?:el)?if\b.*application\/json/;

// Consuming or dispatching the request — everything the guard must precede.
const CONSUMES_BODY = /\bself\.rfile\.read\b|\b_read_json\s*\(|\bjson\.loads\s*\(/;

const indentOf = (line) => line.length - line.trimStart().length;

// The handler body: every line indented deeper than its `def`, up to the first
// non-blank line that dedents back out.
const bodyOf = (lines, defIndex, defIndent) => {
  const body = [];
  for (let i = defIndex + 1; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '') {
      body.push({ line, index: i });
      continue;
    }
    if (indentOf(line) <= defIndent) break;
    body.push({ line, index: i });
  }
  return body;
};

const rule = {
  id: 'on-device-privacy/json-content-type-guard',
  severity: 'blocking',
  description: 'Every mutating dashboard handler must reject non-application/json requests, before reading the body',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: 'the dashboard has no authentication — the application/json content-type requirement is the only thing forcing a cross-origin browser to preflight, and so the only thing stopping any page the user visits from writing to their laugh log',

  run(ctx) {
    const out = [];
    const add = (file, line, what, fix) =>
      out.push({ rule: rule.id, severity: rule.severity, file, line, what, why: rule.why, fix, doc: rule.doc });

    for (const file of ctx.files.filter((f) => f.startsWith('laughcounter/') && f.endsWith('.py'))) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');

      for (let i = 0; i < lines.length; i += 1) {
        const m = MUTATING_HANDLER.exec(lines[i]);
        if (m === null) continue;
        const [, indent, name] = m;
        const body = bodyOf(lines, i, indent.length);

        const readsAt = body.findIndex((b) => READS_CONTENT_TYPE.test(b.line));
        const guardsAt = body.findIndex((b) => GUARDS_ON_JSON.test(b.line));
        if (readsAt === -1 || guardsAt === -1) {
          add(
            file,
            i + 1,
            `${name}() mutates without requiring an application/json content type`,
            'read the request\'s Content-Type first and reply 415 unless it is application/json, before doing any work (see do_POST in laughcounter/dashboard.py)',
          );
          continue;
        }

        // The guard is only a guard if nothing acted on the request before it.
        const consumesAt = body.findIndex((b) => CONSUMES_BODY.test(b.line));
        if (consumesAt !== -1 && consumesAt < Math.max(readsAt, guardsAt)) {
          add(
            file,
            body[consumesAt].index + 1,
            `${name}() reads the request body before it checks the content type`,
            'move the application/json guard above the body read so a non-JSON request is rejected without being acted on',
          );
        }
      }
    }
    return out;
  },
};

export default rule;

